j:jelly.g:evaluate:
		var knowHelp = new SNC.KnowledgeHelper();
		var showCreateIncident = !kbViewInfo.isInPopup && !jelly.sysparm_no_create_incident &&!kbViewInfo.hideFeedbackOptions && RP.getParameterValue('sysparm_class_name') != "kb_knowledge_block";
		var showMoreInfo = !kbViewInfo.isInPopup && !jelly.sysparm_no_info;
		var showUpdateAction = !jelly.sysparm_no_update && isEditable;
		var canUserRead = knowledgeRecord.canRead();
		var showFlagArticle = knowHelp.getBooleanProperty(knowledgeRecord, "glide.knowman.show_flag", true)
								&& !jelly.sysparm_no_suggest
								&& !disableSuggesting && !kbViewInfo.hideFeedbackOptions;
		if(showFlagArticle){
			var roles = gs.getProperty('glide.knowman.show_flag.roles');
			if (roles != null && roles != '')
					showFlagArticle = gs.hasRole(roles);
		}

		var isMobileView = (RP.getParameterValue('sysparm_device') != "" && RP.getParameterValue('sysparm_device') == "mobile");
		isMobileView = isMobileView || GlideMobileExtensions.getDeviceType() == "m";
		var showPillBox = (showCreateIncident || showMoreInfo || showFlagArticle || showUpdateAction || canUserRead);

		var attachToTaskLabel = GlideMetaData.getTableLabel(RP.getParameterValue('sysparm_kb_search_table'));
        attachToTaskLabel = (attachToTaskLabel != null && attachToTaskLabel != "") 
        				? gs.getMessage("Attach to {0}", [attachToTaskLabel]) 
        				: gs.getMessage("Attach to record"); 

        var showAttachToTask = (RP.getParameterValue('sysparm_kb_search_table') != "" && RP.getParameterValue('sysparm_nameofstack') == "kbpop");

